import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('RATES constant has EUR, USD, GBP', () => {
  assert.ok(RATES.EUR);
  assert.ok(RATES.USD);
  assert.ok(RATES.GBP);
});

test('RATES EUR is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES USD is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES GBP is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(1000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085); // 1000 * 1.085 = 1085
});

test('convert EUR to GBP', () => {
  const result = convert(1000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 843); // 1000 * 0.8425 = 842.5, rounded to 843
});

test('convert EUR to EUR', () => {
  const result = convert(1000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1000);
});

test('convert returns fail for unknown currency', () => {
  const result = convert(1000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert with large amount', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000);
});

test('convert rounds to nearest cent', () => {
  // 1000 * 0.8425 = 842.5, rounds to 843
  const result = convert(1000, 'GBP');
  assert.equal(result.value, 843);
});

test('convert with fractional result rounds correctly', () => {
  // Test that rounding is consistent with roundCents
  const amount = 333;
  const result = convert(amount, 'USD');
  const expected = roundCents(amount * RATES.USD);
  assert.equal(result.value, expected);
});

test('formatMoney EUR format', () => {
  const result = formatMoney(1000, 'EUR');
  assert.equal(result, '€10.00');
});

test('formatMoney USD format', () => {
  const result = formatMoney(1085, 'USD');
  assert.equal(result, '$10.85');
});

test('formatMoney GBP format', () => {
  const result = formatMoney(843, 'GBP');
  assert.equal(result, '£8.43');
});

test('formatMoney with thousands separator', () => {
  const result = formatMoney(1234567, 'EUR');
  assert.equal(result, '€12,345.67');
});

test('formatMoney USD with thousands separator', () => {
  const result = formatMoney(1234567, 'USD');
  // 1234567 * 1.085 / 100 = 13394.8
  assert.ok(result.includes('$'));
  assert.ok(result.includes(','));
});

test('formatMoney GBP with thousands separator', () => {
  const result = formatMoney(1234567, 'GBP');
  assert.ok(result.includes('£'));
  assert.ok(result.includes(','));
});

test('formatMoney with zero amount', () => {
  const result = formatMoney(0, 'USD');
  assert.equal(result, '$0.00');
});

test('formatMoney with single digit cents', () => {
  const result = formatMoney(105, 'EUR');
  assert.equal(result, '€1.05');
});

test('formatMoney with unknown currency returns empty string', () => {
  const result = formatMoney(1000, 'JPY');
  assert.equal(result, '');
});

test('formatMoney EUR has euro symbol', () => {
  const result = formatMoney(1000, 'EUR');
  assert.ok(result.includes('€'));
});

test('formatMoney USD has dollar symbol', () => {
  const result = formatMoney(1000, 'USD');
  assert.ok(result.includes('$'));
});

test('formatMoney GBP has pound symbol', () => {
  const result = formatMoney(1000, 'GBP');
  assert.ok(result.includes('£'));
});

test('formatMoney USD converted from EUR', () => {
  const eurCents = 1000;
  const usdResult = convert(eurCents, 'USD');
  const formatted = formatMoney(eurCents, 'USD');

  // formatMoney should use the original EUR cents and apply rate
  assert.ok(formatted.includes('$'));
});

test('formatMoney has exactly 2 decimal places', () => {
  const result = formatMoney(1234, 'EUR');
  assert.ok(result.match(/\.\d{2}$/));
});

test('formatMoney has 2 decimals for all currencies', () => {
  const amounts = [1000, 1234, 105];
  const currencies = ['EUR', 'USD', 'GBP'];

  amounts.forEach(amount => {
    currencies.forEach(currency => {
      const result = formatMoney(amount, currency);
      if (result !== '') {
        assert.ok(result.match(/\.\d{2}$/), `${result} doesn't end with .XX`);
      }
    });
  });
});

test('convert returns integer cents', () => {
  const result = convert(333, 'USD');
  assert.ok(Number.isInteger(result.value));
});

test('convert multiple currencies consistently', () => {
  const eurCents = 10000;
  const usdResult = convert(eurCents, 'USD');
  const gbpResult = convert(eurCents, 'GBP');
  const eurResult = convert(eurCents, 'EUR');

  // All should return ok
  assert.equal(usdResult.ok, true);
  assert.equal(gbpResult.ok, true);
  assert.equal(eurResult.ok, true);

  // EUR should be unchanged
  assert.equal(eurResult.value, eurCents);

  // USD should be larger (1.085 > 1)
  assert.ok(usdResult.value > eurCents);

  // GBP should be smaller (0.8425 < 1)
  assert.ok(gbpResult.value < eurCents);
});

test('formatMoney shows correct currency symbol for each', () => {
  const amount = 1000;
  const eur = formatMoney(amount, 'EUR');
  const usd = formatMoney(amount, 'USD');
  const gbp = formatMoney(amount, 'GBP');

  assert.ok(eur.includes('€'));
  assert.ok(usd.includes('$'));
  assert.ok(gbp.includes('£'));

  assert.ok(!eur.includes('$'));
  assert.ok(!eur.includes('£'));
});

test('roundCents is used in convert', () => {
  // Verify that convert uses rounding
  const amount = 111; // 111 * 0.8425 = 93.5175, should round to 94
  const result = convert(amount, 'GBP');
  const expected = roundCents(amount * RATES.GBP);
  assert.equal(result.value, expected);
});

test('convert case sensitivity', () => {
  // Test that currency codes are case sensitive
  const result = convert(1000, 'eur');
  assert.equal(result.ok, false);
});

test('convert with negative amount', () => {
  const result = convert(-1000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -1085);
});

test('formatMoney with negative amount EUR', () => {
  const result = formatMoney(-1000, 'EUR');
  assert.equal(result, '-€10.00');
});

test('formatMoney with negative amount USD', () => {
  const result = formatMoney(-1000, 'USD');
  assert.ok(result.startsWith('-'));
  assert.ok(result.includes('$'));
});

test('formatMoney with negative amount GBP', () => {
  const result = formatMoney(-1000, 'GBP');
  assert.ok(result.startsWith('-'));
  assert.ok(result.includes('£'));
});

test('convert and formatMoney roundtrip consistency', () => {
  const eurCents = 12345;

  // Convert to USD
  const convertedUsd = convert(eurCents, 'USD');
  assert.equal(convertedUsd.ok, true);

  // Format the original amount in USD
  const formatted = formatMoney(eurCents, 'USD');

  // Both should contain $ and appropriate amount
  assert.ok(formatted.includes('$'));
  const numericPart = formatted.replace(/[^\d.]/g, '');
  const expectedAmount = ((eurCents * RATES.USD) / 100).toFixed(2);
  assert.equal(numericPart, expectedAmount.replace('.', ''));
});

test('formatMoney no currency symbol for unknown currency', () => {
  const result = formatMoney(1000, 'CHF');
  assert.equal(result, '');
});

test('convert result is ok/error structure', () => {
  const okResult = convert(1000, 'USD');
  assert.ok('ok' in okResult);
  assert.ok('value' in okResult || 'error' in okResult);

  const errorResult = convert(1000, 'ABC');
  assert.ok('ok' in errorResult);
  assert.ok('error' in errorResult);
});

test('convert zero in different currencies', () => {
  const eur = convert(0, 'EUR');
  const usd = convert(0, 'USD');
  const gbp = convert(0, 'GBP');

  assert.equal(eur.value, 0);
  assert.equal(usd.value, 0);
  assert.equal(gbp.value, 0);
});

test('formatMoney respects house rules (always string, no throw)', () => {
  const result1 = formatMoney(1000, 'EUR');
  assert.equal(typeof result1, 'string');

  const result2 = formatMoney(1000, 'JPY');
  assert.equal(typeof result2, 'string');

  // Should not throw for invalid inputs
  const result3 = formatMoney(undefined, 'EUR');
  assert.equal(typeof result3, 'string');
});

